// @ts-strict-ignore
import styles from "./category-ticket-selector.module.less";
import { CategoryListProps, ProductWithQuantity } from "@/core/types/state/group-admission/group-admission-types";
import { Fragment } from "react";
import { useTranslation } from "react-i18next";
import ProductPicker from "../product-picker/product-picker";
import RadioPicker from "../radio-picker/radio-picker";
import HighEntranceTicketWarning from "../high-entrance-ticket-warning/high-entrance-ticket-warning";
import { GroupAdmissionHelper } from "@/core/helpers";

const updateQuantityOfProduct = (
  product: ProductWithQuantity,
  quantity: number,
  products: CategoryListProps["productsByVariant"],
) => {
  const updatedQuantityOfProductsMap = new Map(products);

  const existingProductsArray = updatedQuantityOfProductsMap.get(product.productMetadata.entryVariant);
  const updatedProductsArray = existingProductsArray?.map((productOfArray) => {
    if (productOfArray.productId === product.productId) {
      return {
        ...productOfArray,
        quantity: quantity,
      };
    }
    return productOfArray;
  });

  updatedQuantityOfProductsMap.set(product.productMetadata.entryVariant, updatedProductsArray);

  return updatedQuantityOfProductsMap;
};

/**
 * A category ticket selector for each category.
 * Each selector contains a list of products.
 * Each product has a quantity picker.
 * If there is only one product in the category or if the category has a quantity of 1, a radio picker is used instead
 */
const CategoryTicketSelector = ({
  category,
  onCategoryChange,
  selectedDate,
}: {
  category: CategoryListProps;
  onCategoryChange: (value: CategoryListProps) => void;
  selectedDate: Date;
}) => {
  const { selectedQuantityOfCategoryInGroup, productsByVariant, name } = category;
  const productsArray = Array.from(productsByVariant.values()).flat();

  const currentTotalQuantity = productsArray.map((product) => product.quantity).reduce((a, b) => a + b, 0);
  const quantityLeft = selectedQuantityOfCategoryInGroup - currentTotalQuantity;

  const isQuantityPicker = productsArray.length > 1 && selectedQuantityOfCategoryInGroup > 1;

  const selectedProduct = productsArray.find((product) => product.quantity > 0);
  const selectedRadioValue = selectedProduct
    ? GroupAdmissionHelper.getRadioPickerValueFromProduct(selectedProduct)
    : undefined;

  const { t } = useTranslation();
  const headlineText = t("selectTicketStepHeadlineText", [name, selectedQuantityOfCategoryInGroup]);

  const onChangeQuantity = (newQuantityOfProduct: number, product: ProductWithQuantity) => {
    const updatedQuantityOfProducts = updateQuantityOfProduct(product, newQuantityOfProduct, productsByVariant);
    onCategoryChange({ ...category, productsByVariant: updatedQuantityOfProducts });
  };

  const onChangeProduct = (product: ProductWithQuantity) => {
    const resetProductQuantities = (category: CategoryListProps): CategoryListProps => {
      const updatedProducts = new Map(productsByVariant);

      updatedProducts.forEach((productsArray) => {
        productsArray.forEach((product) => {
          product.quantity = 0;
        });
      });

      return { ...category, productsByVariant: updatedProducts };
    };

    const resetCategory = resetProductQuantities(category);

    const updatedQuantityOfProducts = updateQuantityOfProduct(
      product,
      selectedQuantityOfCategoryInGroup,
      resetCategory.productsByVariant,
    );
    onCategoryChange({ ...category, productsByVariant: updatedQuantityOfProducts });
  };

  return (
    <div className={styles.categoryWrapper}>
      <div className={[styles.categoryHeadline, styles[category.type.toLowerCase()]].join(" ")}>
        <p className="body-m bold" data-contentful-label-id="selectTicketStepHeadlineText">
          {headlineText}
        </p>
        <p className="p_small" data-contentful-label-id="selectTicketStepHeadlineInfo">
          {t("selectTicketStepHeadlineInfo")}
        </p>
      </div>
      {productsByVariant &&
        [...productsByVariant].map(
          ([key, products]) =>
            (isQuantityPicker && (
              <Fragment key={name + key}>
                <ul className={styles.productPickerList}>
                  {products.map((product) => (
                    <li key={product.productId} className={styles.productPickerListItem} data-variant={key}>
                      <ProductPicker
                        product={product}
                        changeQuantityOfProduct={onChangeQuantity}
                        totalQuantityLeft={quantityLeft}
                        selectedDate={selectedDate}
                      />
                    </li>
                  ))}
                </ul>
                <HighEntranceTicketWarning selectedDate={selectedDate} products={products} />
                <div className={styles.productListDivider}></div>
              </Fragment>
            )) ||
            (!isQuantityPicker && (
              <Fragment key={name + key}>
                <RadioPicker
                  products={products}
                  categoryName={name}
                  selectedDate={selectedDate}
                  selectedValue={selectedRadioValue}
                  changeProduct={onChangeProduct}
                />
                <HighEntranceTicketWarning selectedDate={selectedDate} products={products} />
                <div className={styles.productListDivider}></div>
              </Fragment>
            )),
        )}
    </div>
  );
};

export default CategoryTicketSelector;
