import styles from "./quantity-picker.module.less";
import { ProductWithQuantity } from "@/core/types/state/group-admission/group-admission-types";
import ProductTextBlock from "../product-text-block/product-text-block";
import QuantitySelectorStyled from "@/core/components/primitives/quantity-selector-styled/quantity-selector-styled";
import { HIGH_ENTRANCE_BLOCKING_BUFFER_MINUTES, useShowHighEntranceWarning } from "@/core/hooks/opening-hours-hooks";
import { DateHelper, TodayHelper } from "@/core/helpers";

const QuantityPicker = ({
  product,
  contentfulProduct,
  currentQuantity,
  selectedDate,
  onChangeQuantity,
  totalQuantityLeft,
}: {
  product: ProductWithQuantity;
  contentfulProduct: any;
  currentQuantity: number;
  selectedDate: Date;
  onChangeQuantity: (quantity: number) => void;
  totalQuantityLeft: number;
}) => {
  const highEntranceWarning = useShowHighEntranceWarning(selectedDate, [product], true);
  const dateTimeOfHighEntrance = highEntranceWarning.showWarning
    ? DateHelper.dateWithModifiedTime(selectedDate, highEntranceWarning.highEntranceStart)
    : undefined;

  const now = TodayHelper.getNow();
  const hasTimePassedOnDateOfVisit = dateTimeOfHighEntrance
    ? DateHelper.addMinutes(now, HIGH_ENTRANCE_BLOCKING_BUFFER_MINUTES) > dateTimeOfHighEntrance
    : false;

  const productName = contentfulProduct?.productName || product.productName;
  const soldOutProduct = !product.dateSlot?.quantity || product.dateSlot?.quantity === 0;
  const maxQuantity = Math.min(currentQuantity + totalQuantityLeft, product.dateSlot?.quantity);
  //The guest should not be able to buy a ticket that is not valid on high entrance days if the time of high entrance has passed
  const shouldDisableBecauseOfHighEntrance = highEntranceWarning.showWarning && hasTimePassedOnDateOfVisit;

  return (
    <>
      <ProductTextBlock
        product={product}
        productName={productName}
        soldOutProduct={soldOutProduct}
        highEntrance={shouldDisableBecauseOfHighEntrance ? highEntranceWarning : { showWarning: false }}
        shortDescription={contentfulProduct?.shortDescription}
      />
      <QuantitySelectorStyled
        quantity={currentQuantity}
        onQuantityChange={onChangeQuantity}
        maxQuantity={maxQuantity}
        parentClassName={styles.productPickerQuantitySelector}
        isDisabled={soldOutProduct || shouldDisableBecauseOfHighEntrance}
        isFullWidth={true}
      />
    </>
  );
};

export default QuantityPicker;
