import { RefObject, useCallback, useRef } from "react";
import styles from "./step-warning.module.less";
import { motion } from "framer-motion";
import animatedScrollTo from "animated-scroll-to";
import { LabelKey } from "@/core/labels/i18n";
import { useTranslation } from "react-i18next";
import Banner from "@/core/components/primitives/banner/banner";

type StepWarningProps = {
  title: LabelKey;
  bodyText: LabelKey | Array<LabelKey>;
  bodyList?: Array<string>;
  verticalOffset?: number;
};

const scrollAndFocus = (focusRef: RefObject<HTMLDivElement>, verticalOffset: number) => {
  setTimeout(() => {
    focusRef.current && animatedScrollTo(focusRef.current, { verticalOffset: verticalOffset, speed: 1000 });
    focusRef?.current?.focus();
  }, 0);
};

/**
 * This hook is used to display and scroll to a warning message in the purchase flow.
 * Since the warning message is a ref to a function, it must be wrapped in a useMemo to avoid re-rendering.
 * @returns { () => void } scrollAndFocusOnWarning -  a function to scroll to and focus on the warning message itself.
 * @returns { () => JSX.Element} StepWarning - The warning message is a ref to a function that returns the warning message JSX-element.
 */
export const useStepWarning = ({ title, bodyText, bodyList, verticalOffset = -104 }: StepWarningProps) => {
  /** @param {MutableRefObject<HTMLDivElement>} warningFocusRef - a ref to the warning message div-element. Used to scroll to and focus on the warning message. */
  const warningFocusRef = useRef<HTMLDivElement>(null);
  const { t } = useTranslation();

  const scrollAndFocusOnWarning = () => scrollAndFocus(warningFocusRef, verticalOffset);

  const StepWarning = useCallback(() => {
    return (
      <motion.div
        initial={{ height: 0, opacity: 0 }}
        animate={{ height: "auto", opacity: 1 }}
        exit={{ height: 0, opacity: 0 }}
        className={styles.wrapper}
        ref={warningFocusRef}
      >
        <Banner type="critical" heading={t(title)} paragraph={t(bodyText)} border announcement="assertive">
          {bodyList && (
            <ul>
              {bodyList.map((item, index) => (
                <li key={index}>{item}</li>
              ))}
            </ul>
          )}
        </Banner>
      </motion.div>
    );
  }, [title, t, bodyText, bodyList]);

  return { scrollAndFocusOnWarning, StepWarning };
};
