import Banner from "@/core/components/primitives/banner/banner";
import { ProductWithQuantity } from "@/core/types/state/group-admission/group-admission-types";
import { useShowHighEntranceWarning } from "@/core/hooks";
import { useTranslation } from "react-i18next";

type Props = {
  selectedDate: Date;
  products: Array<ProductWithQuantity>;
};

const HighEntranceTicketWarning = ({ selectedDate, products }: Props) => {
  const { t } = useTranslation();

  const showHighEntranceWarning = useShowHighEntranceWarning(selectedDate, products);

  if (!showHighEntranceWarning.showWarning) {
    return null;
  }

  return (
    <Banner
      type="darkWarning"
      heading={t("selectTicketStepHighEntranceTitle")}
      paragraph={t("selectTicketStepHighEntranceInformation", [showHighEntranceWarning.highEntranceStart])}
    />
  );
};

export default HighEntranceTicketWarning;
