import { StepProps } from "@/core/types/state/group-admission/group-admission-types";
import styles from "./button-row.module.less";
import { PrimaryButton } from "@/core/components/primitives/parks-button/parks-button";
import { useTranslation } from "react-i18next";
import { LabelKey } from "@/core/labels/i18n";

export type ButtonRowProps = {
  onClickStepComplete: () => void;
  /** Note that `nextStepLabelOverride` should be a label ID passed to the `t` translation function */
  nextStepLabelOverride?: LabelKey;
  nextDisabled?: boolean;
  nextTestId?: string;
} & Partial<StepProps>;
export function ButtonRow({
  onClickStepComplete,
  nextStepLabelOverride,
  stepIndex,
  onClickBack,
  nextDisabled,
  nextTestId,
}: ButtonRowProps) {
  const { t } = useTranslation();

  return (
    <div className={styles.buttonWrapper}>
      {onClickBack && typeof stepIndex !== "undefined" && stepIndex > 0 && (
        <PrimaryButton
          isFullWidth={true}
          onClick={onClickBack}
          className={styles.prevButton}
          label={t("previous")}
          contentfulLabelId="previous"
          complementary={true}
        />
      )}
      <PrimaryButton
        isFullWidth={true}
        onClick={onClickStepComplete}
        isDisabled={nextDisabled}
        label={t(nextStepLabelOverride ?? "nextStep")}
        contentfulLabelId={nextStepLabelOverride ?? "nextStep"}
        testId={nextTestId ?? "next-step-button"}
      />
    </div>
  );
}
